"use strict";

/**
 * Builds a general, resume-grounded interview plan.
 *
 * The plan is generated by an LLM when one is configured; otherwise a
 * deterministic heuristic produces a balanced set of questions from the resume
 * text. Both paths obey the same rules:
 *   - every question is grounded in something the resume actually says;
 *   - questions ask about the candidate's own contributions, decisions,
 *     challenges and results;
 *   - a listed skill is treated as a claim to explore, never as proven ability;
 *   - nothing is invented.
 */

const crypto = require("crypto");
const llm = require("./llm");

const RUBRIC = [
  { key: "clarity", label: "Clarity of explanation" },
  { key: "depth", label: "Depth of understanding" },
  { key: "problemSolving", label: "Problem-solving approach" },
  { key: "contribution", label: "Ability to describe personal contribution" },
];

const SECTION_ALIASES = {
  summary: ["summary", "objective", "profile", "about me", "about", "career objective"],
  education: ["education", "educational background", "academic background", "academics", "academic qualifications", "qualifications", "qualification"],
  skills: ["skills", "technical skills", "core skills", "key skills", "technologies", "tech stack", "technical competencies", "competencies"],
  projects: ["projects", "project", "personal projects", "academic projects", "major projects", "key projects"],
  experience: ["experience", "work experience", "professional experience", "internship", "internships", "employment", "work history", "industrial experience"],
  achievements: ["achievements", "accomplishments", "awards", "honors", "honours", "certifications", "certification", "activities", "extracurricular activities", "publications"],
};

const SECTION_ORDER = ["summary", "education", "skills", "experience", "projects", "achievements"];
const MAX_SECTION_CHARS = 2500;
const MAX_QUESTION_COUNT = 10;

function cleanLine(line) {
  return String(line || "").replace(/\s+/g, " ").trim();
}

function headingKey(line) {
  const cleaned = cleanLine(line).toLowerCase().replace(/[:•\-–—_*]+$/g, "").replace(/^[#*\s]+/, "").trim();
  if (!cleaned || cleaned.length > 45) return null;
  for (const [section, aliases] of Object.entries(SECTION_ALIASES)) {
    if (aliases.includes(cleaned)) return section;
  }
  return null;
}

function toItems(block) {
  if (!block) return [];
  return block
    .split(/\n|(?:^|\s)[•\-–—*]\s+|(?:^|\s)\d+[.)]\s+/)
    .map(cleanLine)
    .filter((item) => item.length > 12);
}

function truncate(text, max) {
  const value = cleanLine(text);
  return value.length > max ? `${value.slice(0, max - 1).trimEnd()}…` : value;
}

/**
 * Split raw resume text into labelled sections. Resumes are wildly inconsistent,
 * so this is deliberately forgiving: unknown headings are ignored and any text
 * before the first recognised heading is treated as a summary.
 */
function splitResumeSections(text) {
  const sections = { summary: "", education: "", skills: "", experience: "", projects: "", achievements: "" };
  const lines = String(text || "").replace(/\r\n?/g, "\n").split("\n");
  let current = null;
  const preamble = [];
  for (const line of lines) {
    const key = headingKey(line);
    if (key) {
      current = key;
      continue;
    }
    if (current) sections[current] += `${line}\n`;
    else preamble.push(line);
  }
  const preambleText = cleanLine(preamble.join(" "));
  if (!sections.summary && preambleText) sections.summary = preambleText;
  for (const key of Object.keys(sections)) {
    sections[key] = cleanLine(sections[key]).slice(0, MAX_SECTION_CHARS);
  }
  return sections;
}

function dedupe(list) {
  const seen = new Set();
  const out = [];
  for (const item of list) {
    const value = cleanLine(item);
    const key = value.toLowerCase();
    if (!value || seen.has(key)) continue;
    seen.add(key);
    out.push(value);
  }
  return out;
}

/** Turn a resume document + parsed sections into a compact fact sheet. */
function resumeFacts(resume, sections) {
  const skillsFromText = toItems(sections.skills).flatMap((item) => item.split(/[,|/]/));
  const skills = dedupe([...(resume.skills || []), ...skillsFromText]).slice(0, 20);
  return {
    name: resume.studentName || "",
    topCategory: resume.topCategory || null,
    summary: sections.summary,
    education: sections.education,
    skills,
    projects: dedupe(toItems(sections.projects)).slice(0, 5),
    experience: dedupe(toItems(sections.experience)).slice(0, 5),
    achievements: dedupe(toItems(sections.achievements)).slice(0, 5),
  };
}

function makeQuestion(question) {
  return {
    id: crypto.randomUUID(),
    text: cleanLine(question.text),
    focus: question.focus || "resume",
    basedOn: question.basedOn || "",
    followUps: (question.followUps || []).map(cleanLine).filter(Boolean).slice(0, 2),
  };
}

/** Deterministic, resume-grounded plan used when no LLM is available. */
function buildHeuristicPlan(facts) {
  const questions = [];
  questions.push(makeQuestion({
    text: "To begin, please give a short introduction and highlight the parts of your background you would most like to discuss today.",
    focus: "opening",
    basedOn: "Introduction",
    followUps: ["Which of these areas do you feel strongest about, and why?"],
  }));

  for (const project of facts.projects.slice(0, 3)) {
    questions.push(makeQuestion({
      text: `Your resume mentions "${truncate(project, 140)}". Can you walk me through your specific contribution to it?`,
      focus: "project",
      basedOn: `Project: ${truncate(project, 80)}`,
      followUps: [
        "What was the hardest technical decision you made here, and why did you choose it?",
        "What was the measurable outcome of this work, and how did you verify it?",
      ],
    }));
  }

  for (const skill of facts.skills.slice(0, 3)) {
    questions.push(makeQuestion({
      text: `Your resume lists ${skill} as a skill. Could you describe a project or task where you actually used it?`,
      focus: "skill",
      basedOn: `Skill: ${skill}`,
      followUps: [
        `What was the most difficult part of working with ${skill}, and how did you handle it?`,
        `What have you not yet done with ${skill} that you would like to learn?`,
      ],
    }));
  }

  for (const job of facts.experience.slice(0, 2)) {
    questions.push(makeQuestion({
      text: `Your resume describes "${truncate(job, 140)}". What were you responsible for day to day?`,
      focus: "experience",
      basedOn: `Experience: ${truncate(job, 80)}`,
      followUps: [
        "What was a challenge you faced there, and how did you resolve it?",
        "What would you do differently if you did that work again?",
      ],
    }));
  }

  if (facts.education) {
    questions.push(makeQuestion({
      text: `Your resume shows "${truncate(facts.education, 140)}" in your education. Which subjects or projects best prepared you for a role like this, and how?`,
      focus: "education",
      basedOn: "Education",
      followUps: ["Was there a course you found unexpectedly difficult, and how did you approach it?"],
    }));
  }

  if (facts.achievements.length) {
    questions.push(makeQuestion({
      text: `You list "${truncate(facts.achievements[0], 140)}" as an achievement. What did you personally do to earn it, and what was the impact?`,
      focus: "achievement",
      basedOn: `Achievement: ${truncate(facts.achievements[0], 80)}`,
      followUps: ["Who else was involved, and what was your part versus theirs?"],
    }));
  }

  questions.push(makeQuestion({
    text: "That covers my questions. Is there anything on your resume you would like to explain or add before we wrap up?",
    focus: "closing",
    basedOn: "Closing",
    followUps: [],
  }));

  return questions.slice(0, MAX_QUESTION_COUNT);
}

function validatePlan(raw) {
  if (!raw || typeof raw !== "object") return null;
  const list = Array.isArray(raw.questions) ? raw.questions : [];
  const questions = [];
  for (const item of list) {
    const text = cleanLine(item?.text);
    if (text.length < 8) continue;
    questions.push(makeQuestion({
      text,
      focus: item?.focus,
      basedOn: item?.basedOn,
      followUps: Array.isArray(item?.followUps) ? item.followUps : [],
    }));
    if (questions.length >= MAX_QUESTION_COUNT) break;
  }
  if (questions.length < 4) return null;
  return questions;
}

const PLAN_SYSTEM_PROMPT =
  "You are an experienced interviewer preparing a GENERAL interview based only on a candidate's resume. " +
  "Rules you must follow:\n" +
  "1. Ground every question in something the resume actually states; never invent experience, employers, or skills.\n" +
  "2. Ask about the candidate's own contributions, decisions, challenges, and results.\n" +
  "3. Treat a listed skill as a claim to explore, not as proven ability.\n" +
  "4. Keep questions neutral and non-leading, and cover the resume in a balanced way.\n" +
  "5. Include one short opening question and one closing question.\n" +
  "6. For each question provide at most 2 follow-up questions that clarify the answer or probe a resume claim.\n" +
  "Return ONLY valid JSON, no prose, matching this schema: " +
  '{"summary": string, "questions": [{"text": string, "focus": "opening|project|skill|experience|education|achievement|closing", "basedOn": string, "followUps": string[]}]}.';

async function buildLlmPlan(interview, facts) {
  const payload = {
    candidate: facts.name,
    intendedField: facts.topCategory,
    summary: facts.summary,
    education: facts.education,
    skills: facts.skills,
    projects: facts.projects,
    experience: facts.experience,
    achievements: facts.achievements,
    interviewType: interview.type || "General",
  };
  const raw = await llm.chatJson(
    [
      { role: "system", content: PLAN_SYSTEM_PROMPT },
      { role: "user", content: `Candidate resume facts (JSON):\n${JSON.stringify(payload, null, 2)}\n\nProduce 6-9 questions.` },
    ],
    { temperature: 0.5, maxTokens: 1800 }
  );
  const questions = validatePlan(raw);
  if (!questions) return null;
  return { questions, summary: cleanLine(raw.summary || "") };
}

/**
 * Generate the interview plan. Returns an object that is stored on the
 * interview document. Never throws for LLM failures - falls back to heuristic.
 */
async function generateQuestionPlan(interview, resume) {
  const sections = splitResumeSections(resume.text);
  const facts = resumeFacts(resume, sections);

  let source = "heuristic";
  let questions = null;
  let summary = "";
  if (llm.available()) {
    try {
      const result = await buildLlmPlan(interview, facts);
      if (result) {
        source = "llm";
        questions = result.questions;
        summary = result.summary;
      }
    } catch (error) {
      console.error("LLM interview plan failed, using heuristic:", error.message);
    }
  }
  if (!questions) questions = buildHeuristicPlan(facts);

  return {
    source,
    generatedAt: new Date(),
    resumeAvailable: true,
    resumeSummary: summary || truncate(facts.summary, 400),
    sections: {
      education: truncate(facts.education, 600),
      skills: facts.skills,
      projects: facts.projects,
      experience: facts.experience,
      achievements: facts.achievements,
    },
    rubric: RUBRIC,
    questions,
    notes: source === "llm"
      ? "Generated by the configured language model from the candidate's resume."
      : "Generated from the resume using a deterministic template (no language model configured).",
  };
}

/**
 * Optionally generate one grounded follow-up to a candidate's answer. Used only
 * when the plan did not already carry a follow-up. Returns null when unavailable
 * or the model output is unusable.
 */
async function generateFollowUp(interview, plan, question, answerText) {
  if (!llm.available() || !answerText) return null;
  try {
    const raw = await llm.chatJson(
      [
        {
          role: "system",
          content:
            "You are an interviewer. Given the question the candidate just answered and their answer, write ONE short follow-up " +
            "question that clarifies their response or explores a claim, staying grounded in their resume. Do not introduce new facts. " +
            'Return ONLY JSON: {"followUp": string}.',
        },
        {
          role: "user",
          content:
            `Resume skills/projects: ${JSON.stringify({ skills: plan?.sections?.skills || [], projects: plan?.sections?.projects || [] })}\n` +
            `Question: ${question.text}\nCandidate answer: ${answerText}\n\nWrite the follow-up.`,
        },
      ],
      { temperature: 0.5, maxTokens: 200 }
    );
    const text = cleanLine(raw?.followUp);
    return text.length >= 8 ? text : null;
  } catch (error) {
    console.error("LLM follow-up failed:", error.message);
    return null;
  }
}

module.exports = { generateQuestionPlan, generateFollowUp, splitResumeSections, buildHeuristicPlan, RUBRIC, MAX_QUESTION_COUNT };
